'use client';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { usePathname, useRouter } from 'next/navigation';
import { i18n } from '@/lib/i18n-config';

export function LanguageSelector({ dictionary }: { dictionary: any }) {
  const router = useRouter();
  const pathname = usePathname();

  const getCurrentLocale = () => {
    const segments = pathname.split('/');
    return segments[1] || i18n.defaultLocale;
  };

  const currentLocale = getCurrentLocale();

  const handleLanguageChange = (newLang: string) => {
    if (!pathname) return;
    const newPath = pathname.replace(`/${currentLocale}`, `/${newLang}`);
    router.push(newPath);
  };

  return (
    <Select onValueChange={handleLanguageChange} value={currentLocale}>
      <SelectTrigger className="w-[180px]">
        <SelectValue placeholder={dictionary.placeholder} />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="en">{dictionary.english}</SelectItem>
        <SelectItem value="es">{dictionary.spanish}</SelectItem>
      </SelectContent>
    </Select>
  );
}
