'use client';

import { useState, useEffect, useCallback } from 'react';

function setCookie(name: string, value: string, days: number) {
    let expires = "";
    if (days) {
        const date = new Date();
        date.setTime(date.getTime() + (days*24*60*60*1000));
        expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + (value || "")  + expires + "; path=/";
}

function getCookie(name: string): string | null {
    const nameEQ = name + "=";
    const ca = document.cookie.split(';');
    for(let i=0;i < ca.length;i++) {
        let c = ca[i];
        while (c.charAt(0)==' ') c = c.substring(1,c.length);
        if (c.indexOf(nameEQ) == 0) return c.substring(nameEQ.length,c.length);
    }
    return null;
}

function eraseCookie(name: string) {   
    document.cookie = name+'=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT;';
}


export const useAuth = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [isAuthenticating, setIsAuthenticating] = useState<boolean>(true);

  useEffect(() => {
    const authStatus = getCookie('is_authenticated') === 'true';
    setIsAuthenticated(authStatus);
    setIsAuthenticating(false);
  }, []);

  const login = useCallback(async () => {
    setCookie('is_authenticated', 'true', 7); // Set cookie for 7 days
    setIsAuthenticated(true);
  }, []);

  const logout = useCallback(() => {
    eraseCookie('is_authenticated');
    setIsAuthenticated(false);
    // The middleware will handle redirecting to the login page
    window.location.reload(); 
  }, []);

  return { isAuthenticated, isAuthenticating, login, logout };
};
